/* Authors: Tom; Brendon (integrator) moved the echo tests to the 240 ms delay and added the union tests (29-30 Oct 2026, with an AI coding assistant). */
#include "unity_fixture.h"

#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include "audio_effects.h"
#include "pitch_detector.h"

#define TEST_TWO_PI 6.2831853071795864769f
#define TEST_BLOCK_SIZE 64U

/* 64-sample blocks in one echo delay (180 at 240 ms). An impulse put in
 * block 0 comes out again at the start of block TEST_ECHO_DELAY_BLOCKS,
 * so a test that wants to see (or rule out) the echo must run that far. */
#define TEST_ECHO_DELAY_BLOCKS (AUDIO_EFFECTS_ECHO_DELAY_SAMPLES / TEST_BLOCK_SIZE)

TEST_GROUP(AudioEffectsTests);

static AudioEffectsState effects;

/** Generate one phase-continuous sine block using an absolute sample offset. */
static void make_sine_block(int16_t *buffer,
                            float frequency_hz,
                            float amplitude,
                            uint32_t sample_offset)
{
    for (uint32_t i = 0U; i < TEST_BLOCK_SIZE; ++i)
    {
        const float phase = TEST_TWO_PI * frequency_hz
                          * (float)(sample_offset + i)
                          / (float)AUDIO_EFFECTS_SAMPLE_RATE_HZ;
        buffer[i] = (int16_t)(amplitude * sinf(phase));
    }
}

/** Generate one sine block while retaining explicit oscillator phase. */
static void make_sine_block_phase(int16_t *buffer,
                                  float frequency_hz,
                                  float amplitude,
                                  float *phase)
{
    const float phase_step = TEST_TWO_PI * frequency_hz
                           / (float)AUDIO_EFFECTS_SAMPLE_RATE_HZ;

    for (uint32_t i = 0U; i < TEST_BLOCK_SIZE; ++i)
    {
        buffer[i] = (int16_t)(amplitude * sinf(*phase));
        *phase += phase_step;
        if (*phase >= TEST_TWO_PI)
        {
            *phase -= TEST_TWO_PI;
        }
    }
}

